package com.quincaisoft.inventory.application;
import com.quincaisoft.inventory.api.*;import com.quincaisoft.inventory.infrastructure.*;import com.quincaisoft.catalog.api.CatalogService;import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.time.*;import java.math.BigInteger;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.function.*;
@Service public class DefaultInventoryJobs implements InventoryJobs {
 private final EntityManager em;private final ScopedTransactions tx;private final StockService stock;private final CatalogService catalog;private final FinanceService finance;private final JsonMapper json=JsonMapper.builder().build();
 public DefaultInventoryJobs(EntityManager em,ScopedTransactions tx,StockService stock,CatalogService catalog,FinanceService finance){this.em=em;this.tx=tx;this.stock=stock;this.catalog=catalog;this.finance=finance;}
 public List<Job> list(String kind){if(!Set.of("COUNT","CUT","REPACK").contains(kind))throw new IllegalArgumentException("Unknown job type");return tx.execute(()->{var s=TenantContext.current();return em.createQuery("select j from InventoryJob j where j.tenantId=:t and j.companyId=:c and j.branchId=:b and j.kind=:k order by j.createdAt desc",InventoryJob.class).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("k",kind).setMaxResults(200).getResultList().stream().map(this::view).toList();});}
 public Job get(UUID id){return tx.execute(()->view(find(id)));}
 private InventoryJob find(UUID id){var s=TenantContext.current();var j=em.find(InventoryJob.class,new InventoryJob.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(j==null||!j.branchId.equals(s.branchId()))throw new NoSuchElementException("Inventory job not found");return j;}
 private Job view(InventoryJob j){return new Job(j.id,j.kind,j.status,j.warehouseId,j.sourceProduct,j.outputProduct,str(j.sourceQuantityMilli),str(j.outputQuantityMilli),str(j.snapshotVersion),str(j.snapshotValueXaf),str(j.postedValueXaf),str(j.version),j.businessDate,j.evidenceReference);}
 private InventoryJob base(UUID warehouse,UUID source,LocalDate date,String kind,String reason){stock.requireWarehouse(warehouse);if(!catalog.get(source).active()||date==null)throw new IllegalArgumentException("Active product and date required");reason(reason);var s=TenantContext.current();var j=new InventoryJob();j.id=UUID.randomUUID();j.tenantId=s.tenantId();j.companyId=s.companyId();j.branchId=s.branchId();j.warehouseId=warehouse;j.sourceProduct=source;j.kind=kind;j.reason=reason;j.businessDate=date;j.createdBy=s.actorId();j.createdAt=Instant.now();j.evidenceReference="";return j;}
 private StockBalance balance(InventoryJob j){em.createNativeQuery("select id from warehouse where tenant_id=:t and company_id=:c and branch_id=:b and id=:w FOR UPDATE").setParameter("t",j.tenantId).setParameter("c",j.companyId).setParameter("b",j.branchId).setParameter("w",j.warehouseId).getSingleResult();var b=em.find(StockBalance.class,new StockBalance.Key(j.tenantId,j.companyId,j.warehouseId,j.sourceProduct),LockModeType.PESSIMISTIC_WRITE);if(b==null||!b.branchId.equals(j.branchId))throw new IllegalStateException("Existing stock position required");return b;}
 public Job startCount(CountStart c){if(c==null||c.operationId()==null)throw new IllegalArgumentException("Operation required");return tx.execute(()->once(c.operationId(),"START_COUNT|"+c,()->{var j=base(c.warehouseId(),c.productId(),c.businessDate(),"COUNT",c.reason());var b=balance(j);j.sourceQuantityMilli=b.quantityMilli;j.snapshotVersion=b.version;j.snapshotValueXaf=b.valueXaf;j.status="COUNTING";em.persist(j);em.flush();return j;}));}
 public Job capture(UUID id,Action c){long actual=quantity(c.quantityMilli(),true);return action(id,c,"CAPTURE",j->{if(!j.kind.equals("COUNT")||!j.status.equals("COUNTING"))throw new IllegalStateException("Started count required");evidence(c.evidenceReference());j.outputQuantityMilli=actual;j.evidenceReference=c.evidenceReference();j.capturedBy=TenantContext.current().actorId();j.status="CAPTURED";});}
 public Job draftTransform(String kind,Transform c){if(!Set.of("CUT","REPACK").contains(kind)||c==null||c.operationId()==null)throw new IllegalArgumentException("Valid transformation required");long source=quantity(c.sourceQuantityMilli(),false),output=quantity(c.outputQuantityMilli(),false);evidence(c.evidenceReference());if(c.sourceProduct().equals(c.outputProduct()))throw new IllegalArgumentException("Distinct source and output SKU required");return tx.execute(()->once(c.operationId(),"TRANSFORM|"+kind+"|"+c,()->{var j=base(c.warehouseId(),c.sourceProduct(),c.businessDate(),kind,c.reason());if(!catalog.get(c.outputProduct()).active())throw new IllegalArgumentException("Output product inactive");j.outputProduct=c.outputProduct();j.sourceQuantityMilli=source;j.outputQuantityMilli=output;j.evidenceReference=c.evidenceReference();j.status="DRAFT";
  if(kind.equals("CUT")){j.parentLengthMm=quantity(c.parentLengthMm(),false);j.outputLengthMm=quantity(c.outputLengthMm(),false);if(!catalog.get(c.sourceProduct()).baseUnit().equals("piece")||!catalog.get(c.outputProduct()).baseUnit().equals("piece")||source!=1000||output%1000!=0||Math.multiplyExact(j.outputLengthMm,output/1000)!=j.parentLengthMm)throw new IllegalArgumentException("Cut requires one piece, whole output pieces and exact zero-loss length conservation");}
  em.persist(j);em.flush();return j;}));}
 public Job approve(UUID id,Action c){return action(id,c,"APPROVE",j->{if(!(j.kind.equals("COUNT")?j.status.equals("CAPTURED"):j.status.equals("DRAFT")))throw new IllegalStateException("Captured count or draft transformation required");var actor=TenantContext.current().actorId();if(actor.equals(j.createdBy)||actor.equals(j.capturedBy))throw new IllegalStateException("Independent approver required");j.approvedBy=actor;j.status="APPROVED";});}
 public Job post(UUID id,Action c){return action(id,c,"POST",j->{if(!j.status.equals("APPROVED")||j.approvedBy==null)throw new IllegalStateException("Approved job required");finance.requireOpenPeriod(j.businessDate);if(j.kind.equals("COUNT")){var b=balance(j);if(b.version!=j.snapshotVersion||b.quantityMilli!=j.sourceQuantityMilli||b.valueXaf!=j.snapshotValueXaf)throw new IllegalStateException("Count snapshot stale; start a new count");long delta=Math.subtractExact(j.outputQuantityMilli,j.sourceQuantityMilli);if(delta!=0){long value;if(delta<0)value=stock.issue(j.warehouseId,j.sourceProduct,Math.negateExact(delta),derived(c.operationId(),"count"),c.reason()).valueXaf();else{value=proportion(j.snapshotValueXaf,delta,j.sourceQuantityMilli);stock.receive(j.warehouseId,j.sourceProduct,delta,value,derived(c.operationId(),"count"),c.reason());}j.postedValueXaf=value;if(value>0)finance.post(j.id,derived(c.operationId(),"journal"),j.businessDate,"INVENTORY_COUNT",delta>0?List.of(new FinanceService.Entry("MERCHANT_INVENTORY",value,0),new FinanceService.Entry("INVENTORY_GAIN",0,value)):List.of(new FinanceService.Entry("INVENTORY_LOSS",value,0),new FinanceService.Entry("MERCHANT_INVENTORY",0,value)));}}
  else{var result=stock.issue(j.warehouseId,j.sourceProduct,j.sourceQuantityMilli,derived(c.operationId(),"input"),c.reason());stock.receive(j.warehouseId,j.outputProduct,j.outputQuantityMilli,result.valueXaf(),derived(c.operationId(),"output"),c.reason());j.postedValueXaf=result.valueXaf();}j.status="POSTED";});}
 private Job action(UUID id,Action c,String verb,Consumer<InventoryJob> work){if(c==null||c.operationId()==null)throw new IllegalArgumentException("Operation required");long version=quantity(c.version(),true);reason(c.reason());return tx.execute(()->once(c.operationId(),verb+"|"+id+"|"+c,()->{var j=find(id);if(j.version!=version)throw new RevisionConflict("Inventory job changed");work.accept(j);em.flush();return j;}));}
 private Job once(UUID op,String material,Supplier<InventoryJob> action){var s=TenantContext.current();String h=hash(material);em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+op).getSingleResult();var prior=em.createNativeQuery("select request_hash,response_json::text from idempotency_result where tenant_id=:t and company_id=:c and branch_id=:b and operation_id=:o").setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",op).getResultList();if(!prior.isEmpty()){Object[] row=(Object[])prior.getFirst();if(!h.equals(row[0])||row[1]==null)throw new IllegalStateException("Operation already used or expired");return json.readValue((String)row[1],Job.class);}var j=action.get();var dto=view(j);em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json)values(:t,:o,:c,:b,:h,'INVENTORY_JOB',:id,cast(:body as jsonb))").setParameter("t",s.tenantId()).setParameter("o",op).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",h).setParameter("id",j.id).setParameter("body",json.writeValueAsString(dto)).executeUpdate();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload)values(:t,:event,:c,:b,:o,'InventoryJobChanged.v1','inventory_job',:id,cast(:body as jsonb))").setParameter("t",s.tenantId()).setParameter("event",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",op).setParameter("id",j.id).setParameter("body",json.writeValueAsString(Map.of("job",dto,"actorId",s.actorId(),"command",material))).executeUpdate();return dto;}
 private static long proportion(long value,long qty,long total){if(total<=0)throw new IllegalStateException("No valuation basis for count gain");var x=BigInteger.valueOf(value).multiply(BigInteger.valueOf(qty)).divideAndRemainder(BigInteger.valueOf(total));if(x[1].signum()!=0)throw new IllegalArgumentException("Count valuation requires fractional FCFA policy");return x[0].longValueExact();}
 private static long quantity(String value,boolean zero){if(value==null||!value.matches(zero?"0|[1-9][0-9]*":"[1-9][0-9]*"))throw new IllegalArgumentException("Integral quantity/version required");return Long.parseLong(value);}
 private static void reason(String value){if(value==null||value.isBlank()||value.length()>2000)throw new IllegalArgumentException("Reason required");}private static void evidence(String value){if(value==null||value.isBlank()||value.length()>240)throw new IllegalArgumentException("Evidence required");}
 private static String str(long v){return Long.toString(v);}private static UUID derived(UUID id,String kind){return UUID.nameUUIDFromBytes((id+":"+kind).getBytes(StandardCharsets.UTF_8));}private static String hash(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
